  ('courses', 'complete-rcpath-dataset-discussion-for-frcpath-part-1-and-part-2', 'complete-rcpath-dataset-discussion-for-frcpath-part-1-and-part-2', 'frcpath-part-2-dataset-discussion-macro', 1, '{"id":"complete-rcpath-dataset-discussion-for-frcpath-part-1-and-part-2","slug":"complete-rcpath-dataset-discussion-for-frcpath-part-1-and-part-2","category":"frcpath-part-2-dataset-discussion-macro","title":"Complete RCPath Dataset Discussion for FRCPath Part 1 and Part 2","tagline":"Three sessions of dataset discussion. Session 1: complete GIT datasets with liver and pancreas plus a model FRCPath Part 2 macro case discussion. Session 2: MGT, FGT and Urinary system dataset discussion plus a model FRCPath Part 2 macro case discussion. Session 3: Skin, Breast, Thyroid, Larynx and Lung dataset discussion plus a model FRCPath Part 2 macro case discussion.","subspecialty":"","examTargets":[],"imageUrl":"","priceCents":400000,"currency":"INR","faculty":{"id":"","name":"","title":"","affiliation":"","avatarUrl":""},"lessonCount":0,"whoFor":[],"whatYouGet":[],"curriculum":[],"faqs":[]}'::jsonb),
