  ('courses', 'frcpath-histopathology-part-1-course', 'frcpath-histopathology-part-1-course', 'frcpath-part-1', 7, '{"id":"frcpath-histopathology-part-1-course","slug":"frcpath-histopathology-part-1-course","category":"frcpath-part-1","title":"FRCPath Part-1 Histopathology Course","tagline":"Salient features: topicwise notes including forensic and governance; practice questions on each topic; question bank with MCQs and EMQs including forensic and governance; interactive videos and high-yield MCQ discussion; topicwise mock tests resembling the real exam; and 5 complete mock tests resembling the real exam. No hard copies will be shipped with the course.","subspecialty":"","examTargets":[],"imageUrl":"","priceCents":799900,"currency":"INR","faculty":{"id":"","name":"","title":"","affiliation":"","avatarUrl":""},"lessonCount":0,"whoFor":[],"whatYouGet":[],"curriculum":[],"faqs":[]}'::jsonb),
  ('courses', 'neuropathology-q-bank-and-tests', 'neuropathology-q-bank-and-tests', 'neuropathology', 8, '{"id":"neuropathology-q-bank-and-tests","slug":"neuropathology-q-bank-and-tests","category":"neuropathology","title":"Neuropathology Course for DM and Fellowships","tagline":"Useful for residents, practising pathologists, DM neuropathology and fellowship aspirants. Benefits: interactive topicwise video lectures; updated questions based on recent pattern; high-yield explanations for every question; WHO 2021 CNS updates covered; complete source of information from standard reference books; and flashcards for easy revision. Videos and Q-Bank cover trauma, peripheral nervous system diseases, inflammation, neurodegenerative diseases and CNS tumors (complete discussion of WHO 5th edition, 2021). Live lectures scheduled weekly. 500+ questions with complete explanations.","subspecialty":"","examTargets":[],"imageUrl":"","priceCents":459900,"currency":"INR","faculty":{"id":"","name":"","title":"","affiliation":"","avatarUrl":""},"lessonCount":0,"whoFor":[],"whatYouGet":[],"curriculum":[],"faqs":[]}'::jsonb),
  ('courses', 'complete-ini-ss-mock-tests-histopathology-hematopathology', 'complete-ini-ss-mock-tests-histopathology-hematopathology', 'ini-ss-mocks', 9, '{"id":"complete-ini-ss-mock-tests-histopathology-hematopathology","slug":"complete-ini-ss-mock-tests-histopathology-hematopathology","category":"ini-ss-mocks","title":"Complete INI-SS Mock Tests (Histopathology + Hematopathology)","tagline":"Consists of 6 complete mock tests and 2 short tests (3 sets of histopathology mock test + 1 short test, and 3 sets of hematopathology mock test + 1 short test). INI-SS pattern mock test: 90 minutes, 80 questions, 80 marks, objective single-correct-choice; +1 correct, -1/3 incorrect; 50% general pathology and 50% speciality. INI-SS pattern short test: 45 minutes, 40 questions, 40 marks, same marking scheme.","subspecialty":"","examTargets":[],"imageUrl":"","priceCents":129900,"currency":"INR","faculty":{"id":"","name":"","title":"","affiliation":"","avatarUrl":""},"lessonCount":0,"whoFor":[],"whatYouGet":[],"curriculum":[],"faqs":[]}'::jsonb),
