  ('courses', 'frcpath-part-1-histopathology-complete-mock-tests', 'frcpath-part-1-histopathology-complete-mock-tests', 'frcpath-part1-mock', 12, '{"id":"frcpath-part-1-histopathology-complete-mock-tests","slug":"frcpath-part-1-histopathology-complete-mock-tests","category":"frcpath-part1-mock","title":"FRCPath Part-1 Histopathology Complete Mock Tests","tagline":"Key features: five complete mock tests curated to match the FRCPath Part-1 Histopathology exam pattern; exam-like proctored experience; previously asked questions included; detailed feedback with strength and weakness analysis for targeted study; fully proctored environment to help manage exam stress; and familiarization with exam format, time management and question types.","subspecialty":"","examTargets":[],"imageUrl":"","priceCents":129900,"currency":"INR","faculty":{"id":"","name":"","title":"","affiliation":"","avatarUrl":""},"lessonCount":0,"whoFor":[],"whatYouGet":[],"curriculum":[],"faqs":[]}'::jsonb),
  ('courses', 'ultimate-frcpath-part-2-study-program', 'ultimate-frcpath-part-2-study-program', 'frcpath-part-2-comprehensive-course', 13, '{"id":"ultimate-frcpath-part-2-study-program","slug":"ultimate-frcpath-part-2-study-program","category":"frcpath-part-2-comprehensive-course","title":"Comprehensive Preparatory Course For FRCPath Part 2 Histopathology","tagline":"A structured, intensive course to help you excel in the FRCPath Part 2 histopathology exams, integrating live sessions, case discussions and hands-on preparation. Course duration: 3 months, 6 months and 1 year. Includes: complete self-learning course with recorded lectures and PDF notes on all key topics; mocks with case discussions (short surgicals, cytology and long cases, previous and tentative exam cases, scanned slides for practice and script writing); script submission and evaluation with personalized feedback; and notes and recordings available after every class for revision.","subspecialty":"","examTargets":[],"imageUrl":"","priceCents":2500000,"currency":"INR","faculty":{"id":"","name":"","title":"","affiliation":"","avatarUrl":""},"lessonCount":0,"whoFor":[],"whatYouGet":[],"curriculum":[],"faqs":[]}'::jsonb),
