  ('courses', 'b-all-mrd-flow-cytometry-assessment-mq8bgcqh', 'b-all-mrd-flow-cytometry-assessment-mq8bgcqh', 'hematopathology', 16, '{"id":"b-all-mrd-flow-cytometry-assessment-mq8bgcqh","slug":"b-all-mrd-flow-cytometry-assessment-mq8bgcqh","category":"hematopathology","title":"B-ALL MRD — Flow Cytometry Assessment","tagline":"Flow cytometry in minimal residual disease. Course overview: B-ALL MRD by next-generation flow cytometry (Dr. Pratyush Mishra). Covers the definition of MRD (detection of residual leukemic cells post-therapy beyond morphologic resolution, by techniques more sensitive than morphology such as flow cytometry or PCR), sensitivity (typically 10^-4 to 10^-6), and its importance for risk stratification and prognosis.","subspecialty":"","examTargets":[],"imageUrl":"","priceCents":0,"currency":"INR","faculty":{"id":"","name":"","title":"","affiliation":"","avatarUrl":""},"lessonCount":0,"whoFor":[],"whatYouGet":[],"curriculum":[],"faqs":[]}'::jsonb),
  ('books', 'concise-histotechniques-notes-for-easy-learning', 'concise-histotechniques-notes-for-easy-learning', null, 0, '{"id":"concise-histotechniques-notes-for-easy-learning","slug":"concise-histotechniques-notes-for-easy-learning","name":"Concise Histotechniques Notes - Hard Copies","description":"The ultimate guide to mastering histologic techniques. Useful for pathology residents, practicing pathologists, histotechnologists and laboratory scientists. Covers essential techniques, protocols and troubleshooting tips — from tissue processing to staining and microscopy — distilled into one convenient, easy-to-read notebook. Includes related multiple choice questions after each chapter. Based on Bancroft''s Theory and Practice of Histologic Techniques, Basic and Advanced Laboratory Techniques in Histopathology and Cytology by D. Pranab Dey, recent updates and standard articles.","imageUrl":"","priceCents":119900,"currency":"INR"}'::jsonb),
  ('books', 'concise-hematopathology-notes-copy', 'concise-hematopathology-notes-copy', null, 1, '{"id":"concise-hematopathology-notes-copy","slug":"concise-hematopathology-notes-copy","name":"Concise Hematopathology Notes - Hard Copies","description":"The ultimate guide to Hematopathology, useful for pathology residents and practicing pathologists preparing for DM Hematopathology and Hematopathology fellowships. Features concise chapter-wise notes, a few multiple choice questions, and case-review based questions.","imageUrl":"","priceCents":299900,"currency":"INR"}'::jsonb),
  ('books', 'cytopathology-chapterwise-comprehensive-notes', 'cytopathology-chapterwise-comprehensive-notes', null, 2, '{"id":"cytopathology-chapterwise-comprehensive-notes","slug":"cytopathology-chapterwise-comprehensive-notes","name":"Cytopathology Comprehensive Notes - Hard copies","description":"An extensive, structured approach to mastering cytopathology concepts, ideal for students, residents and professionals. Key features: detailed, easy-to-follow chapterwise notes; carefully curated MCQs with explanations covering all major topics; exam-oriented preparation; and a durable, portable high-quality copy for note-taking and quick revision.","imageUrl":"","priceCents":199900,"currency":"INR"}'::jsonb),
  ('books', 'general-pathology-chapterwise-notes', 'general-pathology-chapterwise-notes', null, 3, '{"id":"general-pathology-chapterwise-notes","slug":"general-pathology-chapterwise-notes","name":"General Pathology - Chapterwise Notes","description":"General Pathology chapterwise notes covering fundamental pathology concepts.","imageUrl":"","priceCents":199900,"currency":"INR"}'::jsonb),
  ('books', 'histopathology-notes-volumes-1-and-2', 'histopathology-notes-volumes-1-and-2', null, 4, '{"id":"histopathology-notes-volumes-1-and-2","slug":"histopathology-notes-volumes-1-and-2","name":"Histopathology Notes - Volumes 1 and 2 (Hard Copies)","description":"Comprehensive chapterwise histopathology notes. Extra features: highlighted key points, case cloud (with case scenarios), tips to remember, and previously asked questions in FRCPath Histopathology Part-1, DM Histopathology, DM Oncopathology and fellowship exams. Topicwise worksheets with different question types, review questions after each topic, and puzzles for extra retention (logic puzzle, word finder, crosswords). Delivery time: 15-20 business days.","imageUrl":"","priceCents":550000,"currency":"INR"}'::jsonb),
