  ('bundles', 'complete-hard-copy-collection', 'complete-hard-copy-collection', null, 3, '{"id":"complete-hard-copy-collection","slug":"complete-hard-copy-collection","name":"Complete Hard Copy Collection","description":"A collection of books designed for pathology professionals preparing for exams like pathology boards, residency exams, NEET-SS, FRCPath and fellowship entrance exams. Structured for easy reference, combining theory with high-quality microscopic images, flowcharts and tables.","imageUrl":"","priceCents":1299900,"currency":"INR","includes":["Cytopathology Notes","Histopathology Notes","Histopathology Flashcard Booklet","Hematopathology Notes","General Pathology Notes","Histotechniques Notes"]}'::jsonb);
